def transform(grid):
    h = len(grid)
    w = min(map(len, grid))
    counts = Counter(v for row in grid for v in row)

    # Each repeating color is tested as the lattice divider. ARC grids can
    # have longer solid borders split by small colored markers, so use the
    # modal color as scaffold if it gives the regular five-cell tiling.
    scaffold = counts.most_common(1)[0][0]
    rows = [r for r in range(h) if sum(v == scaffold for v in grid[r][:w]) >= 0.70 * w]
    cols = [c for c in range(w) if sum(grid[r][c] == scaffold for r in range(h)) >= 0.70 * h]

    # Fallback to a regular candidate divider when the modal color isn't the grid.
    if len(rows) < 2 or len(cols) < 2:
        best = None
        for color in counts:
            rr = [r for r in range(h) if sum(v == color for v in grid[r][:w]) >= 0.70 * w]
            cc = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.70 * h]
            if len(rr) >= 2 and len(cc) >= 2:
                score = (-(len(rr)+len(cc)), color)
                if best is None or score < best[0]: best = (score,color,rr,cc)
        if best is None: return [row[:] for row in grid]
        _, scaffold, rows, cols = best

    fill_counts = Counter(v for row in grid for v in row if v != scaffold)
    fill = fill_counts.most_common(1)[0][0] if fill_counts else scaffold
    output = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r][c] for r in (r0,r1) for c in (c0,c1)]
            value = corners[0]
            out_row.append(value if value != scaffold and all(v == value for v in corners) else fill)
        output.append(out_row)
    while output and all(v == fill for v in output[0]): output.pop(0)
    while output and all(v == fill for v in output[-1]): output.pop()
    while output and output[0] and all(row[0] == fill for row in output):
        for row in output: row.pop(0)
    while output and output[0] and all(row[-1] == fill for row in output):
