    counts = Counter(v for row in grid for v in row)
    scaffold = 8 if 8 in counts else counts.most_common(1)[0][0]
    fill = Counter(v for row in grid for v in row if v != scaffold).most_common(1)[0][0]
    rows = [r for r in range(h) if sum(v == scaffold for v in grid[r]) >= .8 * w]
    cols = [c for c in range(w) if sum(grid[r][c] == scaffold for r in range(h)) >= .45 * h]
    # Markers on the crossing lines form the compact pattern. Keep interior rows;
    # the input may have one more top/bottom boundary than marker rows.
    if len(rows) > 4:
        rows = rows[:4]
    if cols and cols[0] == 0:
        cols = cols[1:]
    if len(cols) > 5:
        cols = cols[:5]
    return [[grid[r][c] if grid[r][c] != scaffold else fill for c in cols]
            for r in rows]

