        row = []
        for c in range(len(line_cols) - 1):
            marks = []
            for rr in line_rows[r:r+2]:
                for cc in line_cols[c:c+2]:
                    v = grid[rr][cc]
                    if v not in (7, 8):
                        marks.append(v)
            row.append(Counter(marks).most_common(1)[0][0] if marks else 7)
        output.append(row)
    # The repeated pattern's outer frame is excluded from the answer.
    return [row[1:-1] for row in output[1:-1]]


