 "content": "from collections import Counter


def transform(grid):
    """Sample the encoded color matrix at periodic divider intersections."""
    # This family's demos show that a sampled intersection matrix is copied
    # directly, while the tiling dimensions and line periods vary per example.
    h, w = len(grid), len(grid[0])
    palette = Counter(v for row in grid for v in row)
    # Find the periodic separator rows/columns as the lines that are mostly
    # the most common framework color. Evaluate all residues for each period.
    frame = palette.most_common(1)[0][0]

    def line_residue_counts(axis_len, period, is_row):
        scores = []
        for residue in range(period):
            indices = range(residue, axis_len, period)
            score = 0
            for i in indices:
                line = grid[i] if is_row else [grid[r][i] for r in range(h)]
                score += sum(v == frame for v in line) / len(line)
            scores.append((score, residue))
        return max(scores)

    # Determine periods by strongest regular concentrations of framework color.
    row_choices, col_choices = [], []
    for p in range(2, min(10, h) + 1):
        score, residue = line_residue_counts(h, p, True)
        row_choices.append((score, p, residue))
    for p in range(2, min(10, w) + 1):
        score, residue = line_residue_counts(w, p, False)
        col_choices.append((score, p, residue))
    _, rp, rr = max(row_choices)
    _, cp, cr = max(col_choices)
    rows = list(range(rr, h, rp))
    cols = list(range(cr, w, cp))
    # Framework crossings that are unmarked use the dominant non-frame fill.
    fill = Counter(v for row in grid for v in row if v != frame).most_common(1)[0][0]
    sampled = [[fill if grid[r][c] == frame else grid[r][c] for c in cols]
               for r in rows]
    # Trim only fully blank outer rows and columns, retaining all colored codes.
    while sampled and all(v == fill for v in sampled[0]):
        sampled.pop(0)
    while sampled and all(v == fill for v in sampled[-1]):
        sampled.pop()
    if sampled:
        while all(row and row[0] == fill for row in sampled):
            for row in sampled:
                row.pop(0)
        while all(row and row[-1] == fill for row in sampled):
            for row in sampled:
                row.pop()
    return sampled


